'use strict';
const test=require('node:test'),assert=require('node:assert/strict');
const fs=require('node:fs/promises'),{join}=require('node:path'),{tmpdir}=require('node:os');
const {writeBundleManifest,createCompiledSnapshotLoader}=require('./pokemonCatalogBundle');
const COMMIT='a'.repeat(40);
const notice='MIT License\nCopyright (c) 2021 TCGdex\nThe above copyright notice and this permission notice shall be included in all copies.';
async function fixture(t){const root=await fs.mkdtemp(join(tmpdir(),'catalog-bundle-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));await fs.mkdir(join(root,'en'));await fs.writeFile(join(root,'LICENSE'),notice);const sets=[{id:'base1',name:'Base Set',serie:{id:'base',name:'Base'},cardCount:{official:102}}],cards=[{id:'base1-1',localId:'1',name:'Alakazam',category:'Pokemon',set:{id:'base1'},image:'https://assets.tcgdex.net/en/base/base1/1',variants_detailed:[{type:'holo',variantId:'original'}]}];await fs.writeFile(join(root,'en','sets.json'),JSON.stringify(sets));await fs.writeFile(join(root,'en','cards.json'),JSON.stringify(cards));return {root,cards,sets,load:createCompiledSnapshotLoader({directory:root})};}
test('compiled cards preserve exact provider IDs, variants and asset references',async t=>{const f=await fixture(t);await writeBundleManifest({directory:f.root,commit:COMMIT,languages:['en']});const result=await f.load({commit:COMMIT,language:'en'});assert.equal(result.cards[0].id,'base1-1');assert.equal(result.cards[0].localId,'1');assert.equal(result.cards[0].variants_detailed[0].variantId,'original');assert.equal(result.cards[0].image,f.cards[0].image);});
test('a corrupt generated file is rejected before import',async t=>{const f=await fixture(t);await writeBundleManifest({directory:f.root,commit:COMMIT,languages:['en']});await fs.appendFile(join(f.root,'en','cards.json'),' ');await assert.rejects(f.load({commit:COMMIT,language:'en'}),/checksum/);});
test('wrong commit and missing language are not substituted',async t=>{const f=await fixture(t);await writeBundleManifest({directory:f.root,commit:COMMIT,languages:['en']});await assert.rejects(f.load({commit:'b'.repeat(40),language:'en'}),/provenance/);await assert.rejects(f.load({commit:COMMIT,language:'ja'}),/language/);});
test('source file names are never used to guess or repad a card ID',async t=>{const f=await fixture(t);f.cards[0].id='base1-001';await fs.writeFile(join(f.root,'en','cards.json'),JSON.stringify(f.cards));await assert.rejects(writeBundleManifest({directory:f.root,commit:COMMIT,languages:['en']}),/identity/);});
test('an absent upstream license prevents packaging',async t=>{const f=await fixture(t);await fs.unlink(join(f.root,'LICENSE'));await assert.rejects(writeBundleManifest({directory:f.root,commit:COMMIT,languages:['en']}));});
test('bundle file symlinks outside the bundle are rejected',async t=>{const f=await fixture(t),outside=await fs.mkdtemp(join(tmpdir(),'outside-catalog-'));t.after(()=>fs.rm(outside,{recursive:true,force:true}));await fs.writeFile(join(outside,'cards.json'),JSON.stringify(f.cards));await fs.unlink(join(f.root,'en','cards.json'));await fs.symlink(join(outside,'cards.json'),join(f.root,'en','cards.json'));await assert.rejects(writeBundleManifest({directory:f.root,commit:COMMIT,languages:['en']}),/escapes/);});
test('empty and duplicate-language exports cannot be packaged',async t=>{const f=await fixture(t);await assert.rejects(writeBundleManifest({directory:f.root,commit:COMMIT,languages:['en','en']}),/unique/);await fs.writeFile(join(f.root,'en','cards.json'),'[]');await assert.rejects(writeBundleManifest({directory:f.root,commit:COMMIT,languages:['en']}),/export/);});
test('identical duplicate exports preserve raw counts and bytes but load unique records',async t=>{const f=await fixture(t),setBytes=JSON.stringify([f.sets[0],f.sets[0]]),cardBytes=JSON.stringify([f.cards[0],f.cards[0]]);await fs.writeFile(join(f.root,'en','sets.json'),setBytes);await fs.writeFile(join(f.root,'en','cards.json'),cardBytes);const manifest=await writeBundleManifest({directory:f.root,commit:COMMIT,languages:['en']});assert.equal(manifest.languages.en.sets.count,2);assert.equal(manifest.languages.en.cards.count,2);const loaded=await f.load({commit:COMMIT,language:'en'});assert.deepEqual(loaded.sets,f.sets);assert.deepEqual(loaded.cards,f.cards);assert.equal(await fs.readFile(join(f.root,'en','sets.json'),'utf8'),setBytes);assert.equal(await fs.readFile(join(f.root,'en','cards.json'),'utf8'),cardBytes);});
test('conflicting set IDs remain a packaging error with the offending ID',async t=>{const f=await fixture(t);await fs.writeFile(join(f.root,'en','sets.json'),JSON.stringify([f.sets[0],{...f.sets[0],name:'Conflicting name'}]));await assert.rejects(writeBundleManifest({directory:f.root,commit:COMMIT,languages:['en']}),/Conflicting compiled sets ID: base1/);});
test('conflicting card variants cannot be silently discarded',async t=>{const f=await fixture(t);await fs.writeFile(join(f.root,'en','cards.json'),JSON.stringify([f.cards[0],{...f.cards[0],variants_detailed:[{type:'holo',variantId:'different'}]}]));await assert.rejects(writeBundleManifest({directory:f.root,commit:COMMIT,languages:['en']}),/Conflicting compiled cards ID: base1-1/);});
test('direct catalog normalization still rejects duplicate set IDs',async t=>{const f=await fixture(t);assert.throws(()=>require('./pokemonLocalCatalog').normalize({commit:COMMIT,language:'en',cards:f.cards,sets:[...f.sets,...f.sets]}),/Duplicate set ID/);});
